INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'HCF and LCM', 'Find the HCF of 21 and 70.', '7', '2', '12', '11', 'a', 'Prime-factorise both numbers; HCF(21, 70) = 7.', 'easy', '75cd5ca4a9bc32d6c284b7670ad815de');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'HCF and LCM', 'Find the LCM of 12 and 8.', '20', '27', '23', '24', 'd', 'Prime-factorise both numbers; LCM(12, 8) = 24.', 'easy', '34137105b25dcc3b0fb1075eaa8afccb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Unit digit and primes', 'How many prime numbers are there between 20 and 40 (inclusive)?', '6', '4', '8', '7', 'b', 'Check each number from 20 to 40; exactly 4 have no divisor other than 1 and themselves.', 'medium', 'f02d4e36fb99faca2c2b0b4482cde98c');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'HCF and LCM', 'Find the HCF of 105 and 60.', '15', '11', '19', '14', 'a', 'Prime-factorise both numbers; HCF(105, 60) = 15.', 'easy', '16674fe514e2bbe5f7ea22c61e529099');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Number properties', 'What is the sum of the first 11 even numbers?', '132', '136', '137', '128', 'a', 'Sum of first n even numbers = n(n+1); for n = 11 this is 132.', 'easy', 'dec6b8b1079450980cd730009db9df16');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Unit digit and primes', 'What is the unit digit of 2^83?', '3', '6', '2', '8', 'd', 'Unit digits of powers of 2 repeat in a cycle; 83 falls at the position that gives 8.', 'hard', 'ce925a4a5233e677c42ca922147a0083');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Unit digit and primes', 'How many prime numbers are there between 40 and 70 (inclusive)?', '9', '2', '7', '3', 'c', 'Check each number from 40 to 70; exactly 7 have no divisor other than 1 and themselves.', 'medium', '0bb2eca215cddc067b1d7f7f81d3bae5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Unit digit and primes', 'How many prime numbers are there between 30 and 60 (inclusive)?', '7', '11', '12', '10', 'a', 'Check each number from 30 to 60; exactly 7 have no divisor other than 1 and themselves.', 'medium', '4d5203a5be0a5f61d49f98894d235f34');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'HCF and LCM', 'Find the LCM of 42 and 14.', '44', '42', '43', '38', 'b', 'Prime-factorise both numbers; LCM(42, 14) = 42.', 'easy', '3efd6a5c3e7778959006543d95b12c1e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Remainders and divisibility', 'What is the remainder when 909 is divided by 13?', '7', '12', '8', '11', 'b', '909 = 13 × 69 + 12.', 'medium', '5b381190089038f73cc2e0c29f9fcbc1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Number properties', 'What is the sum of the first 17 even numbers?', '301', '306', '302', '305', 'b', 'Sum of first n even numbers = n(n+1); for n = 17 this is 306.', 'easy', 'd1ba7287c498c25aafbf6370c0c729fd');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'number-system', 'Remainders and divisibility', 'Which of these numbers is divisible by 9?', '8766', '8772', '8774', '8767', 'a', 'A number is divisible by 9 when its digit sum is divisible by 9. Digit sum of 8766 = 27.', 'easy', '06701f1c8082559541e93e5ee2aafc1c');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Basic percentage calculations', 'What is 15% of 1500?', '221', '227', '226', '225', 'd', '15/100 × 1500 = 225.', 'easy', '61b337430f2428057104e779b4790e66');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Successive percentage changes', 'A quantity is first increased by 25% and then decreased by 20%. What is the net change?', '2% decrease', '2% increase', 'No change', '5% increase', 'c', 'Multiplier = 125/100 × 80/100 = 1, a net no change.', 'hard', '40efb5c17618b47c3754ec0c3bf33cf8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Successive percentage changes', 'A quantity is first increased by 20% and then decreased by 10%. What is the net change?', '8% increase', '10% increase', '6% increase', '8% decrease', 'a', 'Multiplier = 120/100 × 90/100 = 1.08, a net 8% increase.', 'hard', '6eaa9156cd318cb4b047a67492da8501');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Basic percentage calculations', 'What percentage of 40 is 18?', '41%', '45%', '47%', '40%', 'b', '(18/40) × 100 = 45%.', 'easy', '8b94db38a70a142208e643d8bd8f0508');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Successive percentage changes', 'A quantity is first increased by 50% and then increased by 20%. What is the net change?', '80% decrease', '82% increase', '80% increase', '70% increase', 'c', 'Multiplier = 150/100 × 120/100 = 1.8, a net 80% increase.', 'hard', '67dc6152b07fe845d8009f8994cea353');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Successive percentage changes', 'A quantity is first increased by 20% and then increased by 20%. What is the net change?', '46% increase', '44% increase', '44% decrease', '40% increase', 'b', 'Multiplier = 120/100 × 120/100 = 1.44, a net 44% increase.', 'hard', 'e48aad08e3e0cf53b6d388880b9bd982');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Percentage increase and decrease', 'A price falls by 10% to Rs. 180. What was the original price?', 'Rs. 200', 'Rs. 204', 'Rs. 201', 'Rs. 199', 'a', 'Original × 90/100 = 180, so original = 200.', 'medium', '3281d2e21de7710cfd0a25b24dbeb80e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Basic percentage calculations', 'What is 5% of 1800?', '87', '90', '86', '93', 'b', '5/100 × 1800 = 90.', 'easy', 'd9c7a70fcf7b71459e26fe045f5a4789');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Percentage increase and decrease', 'A price falls by 40% to Rs. 540. What was the original price?', 'Rs. 900', 'Rs. 902', 'Rs. 905', 'Rs. 895', 'a', 'Original × 60/100 = 540, so original = 900.', 'medium', 'c8f3f86ee852691073cd430a502f608e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Percentage increase and decrease', 'A price falls by 20% to Rs. 920. What was the original price?', 'Rs. 1149', 'Rs. 1155', 'Rs. 1154', 'Rs. 1150', 'd', 'Original × 80/100 = 920, so original = 1150.', 'medium', 'b1b85cd7c9a0d02d4ebe3d33b3549713');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Basic percentage calculations', 'What is 60% of 1900?', '1141', '1140', '1136', '1138', 'b', '60/100 × 1900 = 1140.', 'easy', '3bcacb77a31b24a94aee047115e9235a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'percentages', 'Basic percentage calculations', 'What percentage of 120 is 96?', '80%', '75%', '82%', '85%', 'a', '(96/120) × 100 = 80%.', 'easy', '304ecc6bf5a5f0ccc019f82f6193d7f2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Discount and marked price', 'The marked price of a shirt is Rs. 1700. A discount of 10% is given. What is the selling price?', 'Rs. 1532', 'Rs. 1534', 'Rs. 1530', 'Rs. 1533', 'c', 'SP = 1700 × 90/100 = 1530.', 'easy', '6d9c125f8759ce3e45c92819e9269f95');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Discount and marked price', 'A trader marks goods 60% above cost price and then allows a discount of 25%. What is his overall result?', '20% profit', '20% loss', '35% profit', '23% profit', 'a', 'Take CP = 100: marked = 160, SP = 160 × 75/100 = 120, so 20% profit.', 'hard', '424542ea5d76b20a7d2f807ef90b29e1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'An article is sold for Rs. 490 at a loss of 30%. What was its cost price?', 'Rs. 696', 'Rs. 699', 'Rs. 703', 'Rs. 700', 'd', 'CP × 70/100 = 490, so CP = 700.', 'medium', 'ac5fba23e2344923cc727b3eeb746101');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'An article costs Rs. 420 and is sold at a profit of 30%. What is the selling price?', 'Rs. 550', 'Rs. 548', 'Rs. 543', 'Rs. 546', 'd', 'SP = 420 × 130/100 = 546.', 'easy', 'ec64878c779b5d3cd6e5fc15cb2a3592');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'A shopkeeper buys an item for Rs. 740 and sells it for Rs. 814. What is the profit percentage?', '10%', '5%', '8%', '13%', 'a', 'Profit = 74; profit% = 74/740 × 100 = 10%.', 'easy', 'ff9a4c8c60ac2ed6d7eb7e9c0a26024e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'An article sold at a profit of 5% would give a profit of 20% if sold for Rs. 150 more. Find its cost price.', 'Rs. 1004', 'Rs. 999', 'Rs. 1000', 'Rs. 1003', 'c', 'The extra Rs. 150 equals 15% of CP, so CP = 150 × 100/15 = 1000.', 'hard', 'cad1f3c3ea992dfc29d17b284e0cfe5b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'A shopkeeper buys an item for Rs. 660 and sells it for Rs. 924. What is the profit percentage?', '39%', '40%', '37%', '45%', 'b', 'Profit = 264; profit% = 264/660 × 100 = 40%.', 'easy', '9e5271f5f1e01e2d8f5454af63ba83ac');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'A shopkeeper buys an item for Rs. 1000 and sells it for Rs. 1150. What is the profit percentage?', '14%', '10%', '18%', '15%', 'd', 'Profit = 150; profit% = 150/1000 × 100 = 15%.', 'easy', '08bce8e1fec1a9cc7294ca2b1456ead0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Discount and marked price', 'A trader marks goods 20% above cost price and then allows a discount of 10%. What is his overall result?', '10% profit', '8% loss', '11% profit', '8% profit', 'd', 'Take CP = 100: marked = 120, SP = 120 × 90/100 = 108, so 8% profit.', 'hard', '1b12952d980f88ec56cea09cbb8fee34');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Profit and loss basics', 'An article costs Rs. 980 and is sold at a profit of 10%. What is the selling price?', 'Rs. 1075', 'Rs. 1078', 'Rs. 1077', 'Rs. 1083', 'b', 'SP = 980 × 110/100 = 1078.', 'easy', 'd8de34da24c224b4127b3e89c7a6e6c2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Discount and marked price', 'A trader marks goods 20% above cost price and then allows a discount of 25%. What is his overall result?', '10% loss', '7% loss', '10% profit', '5% loss', 'a', 'Take CP = 100: marked = 120, SP = 120 × 75/100 = 90, so 10% loss.', 'hard', '13b364c95b733b730ccd149f4ec3181e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'profit-and-loss', 'Discount and marked price', 'A trader marks goods 25% above cost price and then allows a discount of 20%. What is his overall result?', 'No profit, no loss', '5% profit', '3% loss', '3% profit', 'a', 'Take CP = 100: marked = 125, SP = 125 × 80/100 = 100, so no profit, no loss.', 'hard', '49f7c0f525064a798f4dcf0766c61ea8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Mixtures', 'A 28-litre mixture has milk and water in the ratio 3:1. How much water must be added so the ratio becomes 3:2?', '7 litres', '8 litres', '2 litres', '11 litres', 'a', 'Milk = 21 L, water = 7 L. For 3:2 water must be 14 L, so add 14 - 7 = 7 L.', 'hard', 'ac8ab3d7b53f2bbd3c849aedf008f60f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'In a class of 40 students the ratio of boys to girls is 3:2. How many girls are there?', '20', '17', '16', '13', 'c', 'One part = 40/5 = 8; girls = 2 × 8 = 16.', 'easy', 'f994f5195ec1145f27c9beb8d6b45698');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'If A:B = 2:3 and B:C = 4:5, what is A:C?', '6:20', '8:15', '6:8', '10:12', 'b', 'Make B equal: A:C = (2 × 4) : (3 × 5) = 8:15 = 8:15.', 'hard', '7cf46a9861d9819c76bd72ace988143d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Dividing amounts in a ratio', 'Rs. 1430 is divided among three people in the ratio 1:3:7. What is the smallest share?', 'Rs. 130', 'Rs. 131', 'Rs. 134', 'Rs. 133', 'a', 'One part = 1430/11 = 130; the smallest share is 130 × 1.', 'medium', '886abd8c5d084007d52a3b07f8f389ce');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Mixtures', 'A 25-litre mixture has milk and water in the ratio 4:1. How much water must be added so the ratio becomes 4:3?', '12 litres', '10 litres', '8 litres', '14 litres', 'b', 'Milk = 20 L, water = 5 L. For 4:3 water must be 15 L, so add 15 - 5 = 10 L.', 'hard', '1206ef286b26d91cf03e7b7fd9d2136f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'If A:B = 2:5 and B:C = 3:4, what is A:C?', '5:9', '3:10', '8:15', '10:12', 'b', 'Make B equal: A:C = (2 × 3) : (5 × 4) = 6:20 = 3:10.', 'hard', '1aa8b0bab8ddb9b155b7311629d5cdef');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'If 2 : 3 = 6 : x, find x.', '9', '14', '12', '5', 'a', 'x = 3 × 6/2 = 9.', 'easy', 'cac32e28e2fa61082e2f4f9227bc5015');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'If 2 : 5 = 14 : x, find x.', '35', '36', '34', '37', 'a', 'x = 5 × 14/2 = 35.', 'easy', '0b32f0124fe40b0871afeb854c1ef2a7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Dividing amounts in a ratio', 'Rs. 300 is divided among three people in the ratio 1:3:6. What is the smallest share?', 'Rs. 34', 'Rs. 35', 'Rs. 30', 'Rs. 32', 'c', 'One part = 300/10 = 30; the smallest share is 30 × 1.', 'medium', 'fa2338c68a306ea2047ebe6f99a46543');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'In a class of 63 students the ratio of boys to girls is 4:3. How many girls are there?', '27', '24', '23', '32', 'a', 'One part = 63/7 = 9; girls = 3 × 9 = 27.', 'easy', '63646ca0c52c42b1329f698b07aa84c7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'If 3 : 5 = 24 : x, find x.', '36', '42', '44', '40', 'd', 'x = 5 × 24/3 = 40.', 'easy', '6408d20144c92f71825dfe6935d47dcd');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'ratio-and-proportion', 'Proportion and ratio problems', 'Two numbers are in the ratio 5:7 and their sum is 96. What is the difference between them?', '15', '16', '14', '17', 'b', 'One part = 96/12 = 8; difference = (7 - 5) × 8 = 16.', 'medium', 'ac6c5fa4cbb49a02b80c3de9b16d30bb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Simple averages', 'What is the average of the first 25 even numbers?', '28', '31', '25', '26', 'd', 'Average of first n natural numbers = (n+1)/2; of first n even numbers = n+1.', 'easy', '05d4e95de3cd58b1da63a2faf9b58dd5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average of five numbers is 55. If one of them, 55, is removed, what is the average of the remaining four?', '55', '56', '53', '58', 'a', 'Total = 5 × 55 = 275; remaining total = 275 - 55 = 220; average = 55.', 'medium', '10aa3932f65736ac852b9b3e290ee74c');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average age of 7 people is 39 years. When one person leaves, the average of the rest becomes 38 years. How old was the person who left?', '45 years', '43 years', '49 years', '46 years', 'a', 'Total before = 273; total after = 228; age of the person = 45.', 'hard', '12463b9f18ee238ad53288f6305ddae0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average age of 6 people is 44 years. When one person leaves, the average of the rest becomes 43 years. How old was the person who left?', '44 years', '46 years', '49 years', '51 years', 'c', 'Total before = 264; total after = 215; age of the person = 49.', 'hard', '17dd61e06013057b4f57555efd675b0f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average age of 5 people is 39 years. When one person leaves, the average of the rest becomes 38 years. How old was the person who left?', '41 years', '43 years', '46 years', '40 years', 'b', 'Total before = 195; total after = 152; age of the person = 43.', 'hard', 'f6a5346068204d228bfc7eb3bc673cd3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average of 7 numbers is 40. When one more number is included the average becomes 44. What is the new number?', '72', '71', '76', '67', 'a', 'New total = 8 × 44 = 352; old total = 280; new number = 72.', 'medium', '9007ea348a470812ff7cb92570d1793f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Simple averages', 'Find the average of 45, 43, 25, 32, 40.', '34', '32', '36', '37', 'd', 'Sum = 185; average = 185/5 = 37.', 'easy', '5203a17a4147f254960524095d5a0741');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average of five numbers is 39. If one of them, 51, is removed, what is the average of the remaining four?', '36', '40', '38', '33', 'a', 'Total = 5 × 39 = 195; remaining total = 195 - 51 = 144; average = 36.', 'medium', '7a847c8b014469c5eff26f50dcae4030');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Simple averages', 'What is the average of the first 11 even numbers?', '12', '7', '10', '8', 'a', 'Average of first n natural numbers = (n+1)/2; of first n even numbers = n+1.', 'easy', 'b0f56eaee49b2d6ddf1a89b0acc11f1f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average age of 8 people is 34 years. When one person leaves, the average of the rest becomes 33 years. How old was the person who left?', '45 years', '41 years', '37 years', '43 years', 'b', 'Total before = 272; total after = 231; age of the person = 41.', 'hard', 'ec075b23d9d8ceb719fbf3e1dd89853f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average of five numbers is 45. If one of them, 77, is removed, what is the average of the remaining four?', '39', '37', '32', '40', 'b', 'Total = 5 × 45 = 225; remaining total = 225 - 77 = 148; average = 37.', 'medium', '288f75abeee1610bf7fb6d575c7c1844');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'averages', 'Missing and replaced values', 'The average age of 5 people is 36 years. When one person leaves, the average of the rest becomes 34 years. How old was the person who left?', '40 years', '39 years', '44 years', '48 years', 'c', 'Total before = 180; total after = 136; age of the person = 44.', 'hard', '4137bf6cbbd29ba3a4beec8e62827699');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Amount and doubling', 'A sum of money doubles itself in 25 years at simple interest. What is the rate per annum?', '4%', '9%', '14%', '2%', 'a', 'Interest = principal in 25 years, so R = 100/25 = 4%.', 'hard', 'fabe95e09b934c3a79c469c2ed9a53ba');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Simple interest calculation', 'Find the simple interest on Rs. 7000 at 12% per annum for 3 years.', 'Rs. 2520', 'Rs. 2523', 'Rs. 2525', 'Rs. 2521', 'a', 'SI = P×R×T/100 = 7000×12×3/100 = 2520.', 'easy', '508bb6b4d864be319e491ff371b06af1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Amount and doubling', 'In how many years will a sum triple itself at 5% simple interest per annum?', '39 years', '40 years', '41 years', '38 years', 'b', 'Interest = 2 × principal, so T = 200/5 = 40 years.', 'hard', '77be638b0f0fa963b68467c28ef819a2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Amount and doubling', 'In how many years will a sum triple itself at 25% simple interest per annum?', '5 years', '7 years', '6 years', '8 years', 'd', 'Interest = 2 × principal, so T = 200/25 = 8 years.', 'hard', '2f6e2fc67c1b311762d03dcda10cadbe');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Finding rate, time or principal', 'Simple interest on Rs. 4500 for 3 years is Rs. 1080. Find the rate per annum.', '11%', '3%', '10%', '8%', 'd', 'R = SI×100/(P×T) = 1080×100/(4500×3) = 8%.', 'medium', '1793b79786c24628a33acb8ebb0499f3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Amount and doubling', 'A sum of money doubles itself in 4 years at simple interest. What is the rate per annum?', '26%', '28%', '29%', '25%', 'd', 'Interest = principal in 4 years, so R = 100/4 = 25%.', 'hard', 'c112abdb090e9793e04a1eb24c5fe130');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Finding rate, time or principal', 'In how many years will Rs. 6000 earn Rs. 1440 as simple interest at 6% per annum?', '4 years', '9 years', '1 years', '6 years', 'a', 'T = SI×100/(P×R) = 4 years.', 'medium', 'cc163d8c68e9f1d9767e0f3b002d0c0e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Simple interest calculation', 'Find the simple interest on Rs. 8500 at 5% per annum for 2 years.', 'Rs. 847', 'Rs. 846', 'Rs. 850', 'Rs. 853', 'c', 'SI = P×R×T/100 = 8500×5×2/100 = 850.', 'easy', '20e691b58849044d94382201d0320c7d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Finding rate, time or principal', 'Simple interest on Rs. 9000 for 5 years is Rs. 5400. Find the rate per annum.', '10%', '15%', '12%', '13%', 'c', 'R = SI×100/(P×T) = 5400×100/(9000×5) = 12%.', 'medium', '0c19d1847ed5c76bf83555ad40cef80e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Finding rate, time or principal', 'In how many years will Rs. 2000 earn Rs. 800 as simple interest at 10% per annum?', '14 years', '4 years', '9 years', '1 years', 'b', 'T = SI×100/(P×R) = 4 years.', 'medium', '90a641791db8791426e04b479856ff61');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Simple interest calculation', 'Find the simple interest on Rs. 9500 at 5% per annum for 4 years.', 'Rs. 1905', 'Rs. 1904', 'Rs. 1895', 'Rs. 1900', 'd', 'SI = P×R×T/100 = 9500×5×4/100 = 1900.', 'easy', 'f8668f794b5c18fa3ef1198850d979b4');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'simple-interest', 'Simple interest calculation', 'Find the simple interest on Rs. 8000 at 5% per annum for 3 years.', 'Rs. 1200', 'Rs. 1205', 'Rs. 1202', 'Rs. 1204', 'a', 'SI = P×R×T/100 = 8000×5×3/100 = 1200.', 'easy', '157b757cd22cc8f70c101c452bd5f9d0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Difference between CI and SI', 'Find the difference between compound interest and simple interest on Rs. 12500 at 12% per annum for 2 years.', 'Rs. 175', 'Rs. 185', 'Rs. 180', 'Rs. 182', 'c', 'For 2 years, CI - SI = P × (R/100)² = 12500 × 12²/10000 = 180.', 'hard', '32ae29106a8010d5deb1f74cea2f04ab');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Compound interest calculation', 'What is the compound interest for the first year on Rs. 2000 at 5% per annum?', 'Rs. 105', 'Rs. 100', 'Rs. 97', 'Rs. 103', 'b', 'For the first year, compound interest equals simple interest = P × R/100.', 'easy', '50a547caa30a962b29c00bc10e25669b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Compound interest calculation', 'What will Rs. 2000 amount to in 2 years at 20% compound interest per annum?', 'Rs. 2884', 'Rs. 2876', 'Rs. 2882', 'Rs. 2880', 'd', 'Amount = 2000 × (1 + 20/100)^2 = 2880.', 'medium', 'b2a17a40f1e501fbab3ca4c317afca05');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Growth and doubling', 'At compound interest a sum doubles in 5 years. In how many years will it become 8 times itself?', '12 years', '10 years', '17 years', '15 years', 'd', 'Doubling repeats every 5 years: 8 times = 2^3, so 3 × 5 = 15 years.', 'hard', 'c30d8ae932a1e96401a0e43a89512b9e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Difference between CI and SI', 'Find the difference between compound interest and simple interest on Rs. 2000 at 5% per annum for 2 years.', 'Rs. 10', 'Rs. 9', 'Rs. 5', 'Rs. 4', 'c', 'For 2 years, CI - SI = P × (R/100)² = 2000 × 5²/10000 = 5.', 'hard', 'b95de3afc0e408f1fc07a4288d5082db');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Compound interest calculation', 'What will Rs. 16000 amount to in 3 years at 5% compound interest per annum?', 'Rs. 18522', 'Rs. 18527', 'Rs. 18524', 'Rs. 18526', 'a', 'Amount = 16000 × (1 + 5/100)^3 = 18522.', 'medium', 'e675d831a7a99c423c554e70d3cad8c0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Compound interest calculation', 'What is the compound interest for the first year on Rs. 10000 at 4% per annum?', 'Rs. 395', 'Rs. 399', 'Rs. 398', 'Rs. 400', 'd', 'For the first year, compound interest equals simple interest = P × R/100.', 'easy', '865f24f1b45d9b2052df979a9219781e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Compound interest calculation', 'What will Rs. 12500 amount to in 2 years at 4% compound interest per annum?', 'Rs. 13515', 'Rs. 13523', 'Rs. 13520', 'Rs. 13517', 'c', 'Amount = 12500 × (1 + 4/100)^2 = 13520.', 'medium', '6cc8aa3f60ed5e45ff3b1e8e14d4a909');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Growth and doubling', 'At compound interest a sum doubles in 5 years. In how many years will it become 4 times itself?', '10 years', '8 years', '9 years', '12 years', 'a', 'Doubling repeats every 5 years: 4 times = 2^2, so 2 × 5 = 10 years.', 'hard', 'fe392f5f43884e9510ac2b3811d3a824');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Growth and doubling', 'At compound interest a sum doubles in 4 years. In how many years will it become 4 times itself?', '5 years', '3 years', '4 years', '8 years', 'd', 'Doubling repeats every 4 years: 4 times = 2^2, so 2 × 4 = 8 years.', 'hard', '47ef823bedb555fb2be1af5882a4f02f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Compound interest calculation', 'Find the compound interest on Rs. 2500 at 12% per annum for 2 years (compounded annually).', 'Rs. 632', 'Rs. 641', 'Rs. 635', 'Rs. 636', 'd', 'Amount = 2500 × (1 + 12/100)^2 = 3136; CI = 3136 - 2500 = 636.', 'medium', '01c5b4aba539b52c5bd76e56c956ed0a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'compound-interest', 'Growth and doubling', 'At compound interest a sum doubles in 3 years. In how many years will it become 8 times itself?', '11 years', '10 years', '9 years', '8 years', 'c', 'Doubling repeats every 3 years: 8 times = 2^3, so 3 × 3 = 9 years.', 'hard', '929fce174c87a85adb579790c4cc2631');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Basic time and work', '12 men can finish a work in 10 days. How many days will 8 men take?', '16 days', '15 days', '20 days', '14 days', 'b', 'Man-days = 12 × 10 = 120; days for 8 men = 120/8 = 15.', 'medium', '9e255c0c89e49e54c56ad9694c41e399');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Basic time and work', 'A worker completes 1/3 of a job in 5 days. How many days will he take to finish the whole job?', '15 days', '19 days', '13 days', '11 days', 'a', 'If 1/3 takes 5 days, the whole job takes 3 × 5 = 15 days.', 'easy', 'b2b899913ec9f9acc5653e56fa24fe36');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Pipes and tanks', 'A pipe fills a tank in 12 hours and a drain empties it in 24 hours. If both are open, how many hours to fill the empty tank?', '20 hours', '22 hours', '24 hours', '26 hours', 'c', 'Net rate = 1/12 - 1/24 = 12/288, so 24 hours.', 'hard', '71c786d63c16f8cc9f4986e7bd681db0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Basic time and work', '10 men can finish a work in 18 days. How many days will 12 men take?', '11 days', '19 days', '15 days', '16 days', 'c', 'Man-days = 10 × 18 = 180; days for 12 men = 180/12 = 15.', 'medium', '36c36dc7d0c465e3d9787867787417d9');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Basic time and work', '5 men can finish a work in 12 days. How many days will 6 men take?', '7 days', '10 days', '13 days', '8 days', 'b', 'Man-days = 5 × 12 = 60; days for 6 men = 60/6 = 10.', 'medium', '8df45a2600524af8e28a66fa2732947d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Basic time and work', 'A worker completes 1/3 of a job in 8 days. How many days will he take to finish the whole job?', '23 days', '22 days', '21 days', '24 days', 'd', 'If 1/3 takes 8 days, the whole job takes 3 × 8 = 24 days.', 'easy', '57fe6b59f8ea152f23106216b979f1e3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Pipes and tanks', 'A pipe fills a tank in 9 hours and a drain empties it in 18 hours. If both are open, how many hours to fill the empty tank?', '17 hours', '13 hours', '18 hours', '22 hours', 'c', 'Net rate = 1/9 - 1/18 = 9/162, so 18 hours.', 'hard', 'b45a2d5c6e9e792acb639db54147df21');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Combined work', 'A and B together finish a work in 8 days. A alone takes 12 days. How long would B take alone?', '19 days', '27 days', '24 days', '26 days', 'c', '1/B = 1/8 - 1/12 = 1/24, so B needs 24 days.', 'hard', 'f1d0ce2c820631381e493e36d61f9790');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Basic time and work', 'A worker completes 1/5 of a job in 8 days. How many days will he take to finish the whole job?', '38 days', '36 days', '41 days', '40 days', 'd', 'If 1/5 takes 8 days, the whole job takes 5 × 8 = 40 days.', 'easy', '1b72a02b436fa10ac98e27f72d109386');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Combined work', 'A can complete a job in 30 days and B in 45 days. Working together, how many days do they need?', '21 days', '19 days', '16 days', '18 days', 'd', 'Together they do 1/30 + 1/45 = 75/1350 of the work per day, so 18 days.', 'medium', '7e05ffa8fe947ac5b9090fc4ac30f2d5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Combined work', 'A can complete a job in 18 days and B in 36 days. Working together, how many days do they need?', '14 days', '17 days', '12 days', '10 days', 'c', 'Together they do 1/18 + 1/36 = 54/648 of the work per day, so 12 days.', 'medium', 'f6212eab3e04c85da488b1aea21703cb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-and-work', 'Combined work', 'A and B together finish a work in 9 days. A alone takes 12 days. How long would B take alone?', '35 days', '32 days', '36 days', '40 days', 'c', '1/B = 1/9 - 1/12 = 1/36, so B needs 36 days.', 'hard', '0f2187e9c1714ce65d20068517ef2aa7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'A 300 m long train crosses a pole in 20 seconds. What is its speed in km/h?', '50 km/h', '53 km/h', '54 km/h', '59 km/h', 'c', 'Speed = 300/20 m/s = 15 m/s = 54 km/h.', 'medium', 'b859d38d70d508d41cc9f4c7a925067e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Speed, distance and time', 'Convert 180 km/h into m/s.', '55 m/s', '50 m/s', '48 m/s', '47 m/s', 'b', 'Multiply km/h by 5/18 to get m/s.', 'easy', '7f6b2b56e1dbb816e2816a4c1edb33b5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'A 150 m long train crosses a pole in 10 seconds. What is its speed in km/h?', '53 km/h', '54 km/h', '51 km/h', '55 km/h', 'b', 'Speed = 150/10 m/s = 15 m/s = 54 km/h.', 'medium', '318a181e83819dee5973bbe2e260a2b3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Average and relative speed', 'Two cars start 200 km apart and drive toward each other at 60 km/h and 40 km/h. After how many hours do they meet?', '1 hours', '12 hours', '2 hours', '7 hours', 'c', 'Closing speed = 100 km/h; time = 200/100 = 2 h.', 'medium', '9a6e3dc714a5f4d1d59952a658c57585');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'Two trains run in opposite directions at 18 km/h and 18 km/h. Their total length is 80 m. How many seconds do they take to cross each other?', '8 seconds', '12 seconds', '7 seconds', '4 seconds', 'a', 'Relative speed = 36 km/h = 10 m/s; time = 80/10 = 8 s.', 'hard', '35eafaf55c0b9c0da7544089a08748a0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'Two trains run in opposite directions at 36 km/h and 36 km/h. Their total length is 120 m. How many seconds do they take to cross each other?', '4 seconds', '9 seconds', '6 seconds', '5 seconds', 'c', 'Relative speed = 72 km/h = 20 m/s; time = 120/20 = 6 s.', 'hard', 'c585cd3d4f25432fd593de78647564f5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'Two trains run in opposite directions at 48 km/h and 60 km/h. Their total length is 240 m. How many seconds do they take to cross each other?', '13 seconds', '8 seconds', '3 seconds', '9 seconds', 'b', 'Relative speed = 108 km/h = 30 m/s; time = 240/30 = 8 s.', 'hard', '98c8ae78d5396280a9f12ca488cf4a42');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'A boat\'s speed in still water is 18 km/h and the stream flows at 6 km/h. How many hours does it take to go 72 km downstream?', '13 hours', '2 hours', '3 hours', '7 hours', 'c', 'Downstream speed = 18 + 6 = 24 km/h; time = 72/24.', 'medium', 'bbc7ab0f3ca896f6240e77a775721b32');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Speed, distance and time', 'A car moves at 40 km/h for 3 hours. How far does it travel?', '120 km', '125 km', '123 km', '121 km', 'a', 'Distance = speed × time = 40 × 3 = 120 km.', 'easy', '45116dcd088ca9b3e83013502f0f3ba5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Speed, distance and time', 'A car moves at 60 km/h for 4 hours. How far does it travel?', '242 km', '240 km', '244 km', '241 km', 'b', 'Distance = speed × time = 60 × 4 = 240 km.', 'easy', '1d4238e4da8569f8ecccbf83acd56cd9');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Speed, distance and time', 'A car moves at 45 km/h for 4 hours. How far does it travel?', '180 km', '184 km', '176 km', '179 km', 'a', 'Distance = speed × time = 45 × 4 = 180 km.', 'easy', '38849192b3e345a90bd4aa757e2c46f9');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'time-speed-distance', 'Trains and boats', 'A boat\'s speed in still water is 10 km/h and the stream flows at 2 km/h. How many hours does it take to go 96 km downstream?', '8 hours', '4 hours', '11 hours', '12 hours', 'a', 'Downstream speed = 10 + 2 = 12 km/h; time = 96/12.', 'medium', '0d54f5981a169b8d338a4db5b803957e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Ratio of ages', 'The ages of two friends are in the ratio 2:3 and their ages add up to 60 years. What is the age of the younger friend?', '24 years', '25 years', '29 years', '22 years', 'a', 'One part = 60/5 = 12; younger = 2 × 12 = 24.', 'easy', '65564f3e2025bda9333ec50194dbf4ac');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Ratio of ages', 'The ages of two friends are in the ratio 4:5 and their ages add up to 54 years. What is the age of the younger friend?', '24 years', '28 years', '22 years', '23 years', 'a', 'One part = 54/9 = 6; younger = 4 × 6 = 24.', 'easy', '8a76e122d9b72ecd05df08ad3381a715');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Present age from conditions', 'Riya is 9 years older than Sana. If Sana is 29 years old now, how old will Riya be after 3 years?', '41 years', '45 years', '44 years', '46 years', 'a', 'Riya now = 29 + 9 = 38; after 3 years = 41.', 'easy', '9ce70a4e05d7cacb707d7b97828145f1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Ratio of ages', 'The ages of two friends are in the ratio 3:5 and their ages add up to 96 years. What is the age of the younger friend?', '34 years', '39 years', '36 years', '37 years', 'c', 'One part = 96/8 = 12; younger = 3 × 12 = 36.', 'easy', '180207b92a784b6604554cb567a56200');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Present age from conditions', 'Riya is 5 years older than Sana. If Sana is 24 years old now, how old will Riya be after 5 years?', '37 years', '30 years', '35 years', '34 years', 'd', 'Riya now = 24 + 5 = 29; after 5 years = 34.', 'easy', 'e9781ae5ac4ed3d6027cc73d0caf99e8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Present age from conditions', 'Riya is 7 years older than Sana. If Sana is 19 years old now, how old will Riya be after 5 years?', '31 years', '34 years', '36 years', '26 years', 'a', 'Riya now = 19 + 7 = 26; after 5 years = 31.', 'easy', '2143de4572f54602a3cd48d285fcecb7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Present age from conditions', 'Riya is 6 years older than Sana. If Sana is 25 years old now, how old will Riya be after 2 years?', '28 years', '38 years', '33 years', '37 years', 'c', 'Riya now = 25 + 6 = 31; after 2 years = 33.', 'easy', 'b429bd90db859f15fb6f45ae0e9ebf96');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Present age from conditions', 'A father is 43 years old and his daughter is 25. How many years ago was the father exactly 2 times as old as the daughter?', '7 years', '5 years', '12 years', '6 years', 'a', '43 - y = 2(25 - y) gives y = 7.', 'hard', '71961c62d1bb016b9a8159b5c7e7dd06');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Ratio of ages', 'The ages of two friends are in the ratio 4:5 and their ages add up to 36 years. What is the age of the younger friend?', '15 years', '21 years', '11 years', '16 years', 'd', 'One part = 36/9 = 4; younger = 4 × 4 = 16.', 'easy', '8df0be21387f4b7e4f18071caca541bf');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Present age from conditions', 'The sum of the present ages of a father and his son is 64 years. After 6 years the father will be 3 times as old as the son. What is the son\'s present age?', '13 years', '12 years', '17 years', '18 years', 'a', 'Let son = x. Then father = 64 - x and 64 - x + 6 = 3(x + 6); solving gives x = 13.', 'medium', '592fbe05f36b6922eda3d62888cb52cf');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Ratio of ages', 'The ages of two friends are in the ratio 3:4 and their ages add up to 70 years. What is the age of the younger friend?', '25 years', '30 years', '29 years', '28 years', 'b', 'One part = 70/7 = 10; younger = 3 × 10 = 30.', 'easy', '63729037203cd8fa0ce397f878126a32');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'problems-on-ages', 'Ratio of ages', 'The ages of two friends are in the ratio 3:4 and their ages add up to 77 years. What is the age of the younger friend?', '37 years', '38 years', '33 years', '32 years', 'c', 'One part = 77/7 = 11; younger = 3 × 11 = 33.', 'easy', 'bbc484efd2db941c3b713920aeb0441d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Coins and dice', 'A fair six-sided die is rolled once. What is the probability of getting a multiple of 3?', '1/6', '1/2', '1/3', '5/6', 'c', '2 favourable outcomes out of 6.', 'easy', '01aff657ef3764e61f64e4402f0cd50f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Balls and bags', 'A bag holds 2 red, 5 blue and 4 green balls. One ball is drawn at random. What is the probability that it is not red?', '2/11', '9/11', '3/4', '5/11', 'b', 'Not red = 9 balls out of 11.', 'easy', '14167f754e0d622f9054fe8c1e3212a0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Coins and dice', 'A fair coin is tossed 4 times. What is the probability of getting exactly 1 head?', '5/16', '1/4', '1/2', '1/16', 'b', 'Favourable = C(4,1) = 4; total = 2^4 = 16.', 'medium', '27791e7ce41ce49b66e213a2c9105c6f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Cards', 'One card is drawn from a well-shuffled deck of 52 cards. What is the probability that it is a black queen?', '2/51', '1/26', '1/13', '3/52', 'b', '2 favourable cards out of 52.', 'easy', '04f7b95bed442784c18e01923984daa3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Cards', 'One card is drawn from a well-shuffled deck of 52 cards. What is the probability that it is a red card?', '26/51', '27/52', '7/13', '1/2', 'd', '26 favourable cards out of 52.', 'easy', '36015dff04144fc1e241d03db93f6c6a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Cards', 'One card is drawn from a well-shuffled deck of 52 cards. What is the probability that it is a spade or an ace?', '17/52', '16/51', '4/13', '9/26', 'c', '16 favourable cards out of 52.', 'easy', '63f408d50ca6a68b3653b45eb3c18354');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Balls and bags', 'A bag has 5 red and 4 blue balls. Two balls are drawn without replacement. What is the probability that both are red?', '5/18', '25/81', '5/9', '1/6', 'a', 'C(5,2)/C(9,2) = 10/36.', 'hard', 'a5b75fbc7e9ea1d7ac06d5edc7baa760');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Coins and dice', 'Two fair dice are rolled. What is the probability that the sum is 11?', '1/18', '1/9', '1/6', '1/12', 'a', '2 of the 36 equally likely outcomes give a sum of 11.', 'medium', 'a61822b7532f72cf494917cc77930bf8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Cards', 'One card is drawn from a well-shuffled deck of 52 cards. What is the probability that it is a king?', '1/13', '5/52', '3/26', '4/51', 'a', '4 favourable cards out of 52.', 'easy', '4928f60d9529e1d4c9fd5b8f49a39d54');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Cards', 'One card is drawn from a well-shuffled deck of 52 cards. What is the probability that it is a heart?', '15/52', '7/26', '1/4', '13/51', 'c', '13 favourable cards out of 52.', 'easy', '9c3acd31108360fcbd214a1379611377');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Coins and dice', 'Two fair dice are rolled. What is the probability that the sum is 8?', '5/36', '7/36', '1/6', '5/12', 'a', '5 of the 36 equally likely outcomes give a sum of 8.', 'medium', 'a3f182cfbecc96d9efe711b6f98fce07');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'probability', 'Coins and dice', 'A fair coin is tossed 4 times. What is the probability of getting exactly 3 heads?', '5/16', '1/16', '1/4', '3/4', 'c', 'Favourable = C(4,3) = 4; total = 2^4 = 16.', 'medium', 'e6cc5fe6dd26c4fbc16d88eaf6c19353');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'In how many ways can 9 people be seated around a circular table?', '40320', '40317', '40319', '40315', 'a', '(n-1)! = 40320.', 'medium', '651a175ec99cb38040ca1d0a3c7b6db1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'In how many ways can 8 people be seated in a row?', '40320', '40319', '40317', '40324', 'a', 'n! = 40320.', 'medium', '2c57de29ecca2955714c7402ce5fc0f9');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'In how many ways can 8 people be seated around a circular table?', '5035', '5040', '5037', '5044', 'b', '(n-1)! = 5040.', 'medium', '49104aa4846b049d5a430591752965be');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'A committee of 4 is to be formed from 6 men and 5 women. In how many ways can it be formed with exactly 2 women?', '145', '151', '153', '150', 'd', 'C(5,2) × C(6,2) = 10 × 15.', 'hard', '94f2b215b2f443ec16268055c809749a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'How many 4-digit numbers can be formed using the digits 1 to 6 if repetition is allowed?', '1294', '1297', '1296', '1299', 'c', 'n^k = 1296.', 'medium', 'd89cacb848c1d2f80d9a2525de75d1aa');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Arrangements of letters', 'In how many different ways can the letters of the word MARKET be arranged?', '721', '716', '717', '720', 'd', '6! divided by factorials of repeated letters (none repeated) = 720.', 'medium', 'a1672095d9b82f5d5c008d5d97bcadc5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'A committee of 3 is to be formed from 6 men and 4 women. In how many ways can it be formed with exactly 1 woman?', '64', '58', '59', '60', 'd', 'C(4,1) × C(6,2) = 4 × 15.', 'hard', 'dd4007e5199faa27d5694a4b9d00a092');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'nPr and nCr', 'Evaluate 8P2.', '60', '56', '54', '59', 'b', '8P2 = n!/(n-k)! = 56.', 'easy', '1a74b76bfa106242172c61c55097b003');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Arrangements of letters', 'In how many different ways can the letters of the word BANANA be arranged?', '63', '62', '61', '60', 'd', '6! divided by factorials of repeated letters (A ×3, N ×2) = 60.', 'medium', 'c597625958e52532c3d04b316e390692');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'How many 3-digit numbers can be formed using the digits 1 to 5 if repetition is allowed?', '126', '122', '124', '125', 'd', 'n^k = 125.', 'medium', '0fd8dc9ab5dabf18daae96b36a27461f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Selections and counting', 'In a meeting of 7 people everyone shakes hands with everyone else exactly once. How many handshakes take place?', '18', '26', '21', '17', 'c', 'C(7,2) = 21.', 'easy', '28d6781febcea170ba9a92345ad7b994');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'permutation-combination', 'Arrangements of letters', 'In how many different ways can the letters of the word GARDEN be arranged?', '720', '723', '724', '719', 'a', '6! divided by factorials of repeated letters (none repeated) = 720.', 'medium', 'b05c6ca4b5855172817f4669f88208f7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Quadratic equations', 'Find the roots of x² - 13x + 36 = 0.', '4 and 9', '-4 and -9', '4 and 10', '5 and 9', 'a', 'Factorise: (x - 4)(x - 9) = 0.', 'medium', 'ac803aa15887ca48a6277b47263bcca3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Linear equations', 'Solve for x: 4x + 20 = 68.', '13', '15', '12', '17', 'c', '4x = 48, so x = 12.', 'easy', 'a668b136101cb082668939d452523596');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Identities and expressions', 'If a + 1/a = 8, find the value of a² + 1/a².', '62', '64', '63', '65', 'a', 'Square both sides: a² + 2 + 1/a² = 64, so a² + 1/a² = 62.', 'medium', 'f1bea30d9e77f963f3de3c10f32cd1ec');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Quadratic equations', 'What is the sum of the roots of x² - 6x + 8 = 0?', '5', '9', '6', '1', 'c', 'For ax² + bx + c = 0, the sum of roots is -b/a.', 'easy', 'b5803ff1421af650bf3dfa54b7e4514b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Quadratic equations', 'Find the roots of x² - 14x + 45 = 0.', '5 and 10', '5 and 9', '-5 and -9', '6 and 9', 'b', 'Factorise: (x - 5)(x - 9) = 0.', 'medium', 'fba4cc24d24715eff92c7c122543477f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Linear equations', 'Solve for x: 8x + 3 = 51.', '1', '7', '4', '6', 'd', '8x = 48, so x = 6.', 'easy', 'cf3ed93f502659f618fed040c2fb7bc2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Linear equations', 'Solve for x: 7x + 4 = 88.', '15', '12', '16', '8', 'b', '7x = 84, so x = 12.', 'easy', '127411f8693b25735fe2d687dc6ebe9f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Linear equations', 'Solve for x: 9x + 16 = 79.', '4', '11', '7', '8', 'c', '9x = 63, so x = 7.', 'easy', '991f223a9e4ccfceb89d8f33f2ae54bf');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Identities and expressions', 'If x + y = 10 and xy = 15, find x² + y².', '69', '70', '75', '71', 'b', 'x² + y² = (x + y)² - 2xy = 100 - 30 = 70.', 'hard', 'f7d89ba27298733dc922979f1ee052e3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Quadratic equations', 'What is the sum of the roots of x² - 9x + 8 = 0?', '13', '11', '5', '9', 'd', 'For ax² + bx + c = 0, the sum of roots is -b/a.', 'easy', '05438d090cd25496c5fa7eadb9325a55');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'algebra', 'Linear equations', 'Solve for x: 3x + 8 = 26.', '11', '10', '6', '4', 'c', '3x = 18, so x = 6.', 'easy', 'c089cd06e6e7f14cb19fa9750c5d91a9');
