INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'geometry', 'Right triangles', 'The two shorter sides of a right-angled triangle are 9 cm and 40 cm. Find the hypotenuse.', '41 cm', '43 cm', '39 cm', '44 cm', 'a', '√(9² + 40²) = 41.', 'easy', '6fbfefdb3915f46e23bc2bedafccd48b');
