INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'geometry', 'Angles and triangles', 'In a triangle, two interior angles are 43° and 63°. What is the exterior angle formed at the third vertex?', '111°', '106°', '109°', '102°', 'b', 'An exterior angle equals the sum of the two opposite interior angles.', 'medium', '4fd70bdc82b8537903f35ce3f0ac09a6');
