INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Numerical Ability', 'data-interpretation', 'Reading tables', 'Units sold (in hundreds):\nProduct | 2024 | 2025\nLaptops | 300 | 240\nMonitors | 160 | 200\nPhones | 340 | 306\nPrinters | 400 | 300\n\nBy how many hundred units did Phones sales change from 2024 to 2025 (ignore the sign)?', '36', '39', '34', '33', 'c', '|306 - 340| = 34.', 'easy', 'e6a0eddfa07e506128c459cf4d3cff0b');
