INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Alphabet position', 'Which letter is 3 places after G and 3 places before M?', 'L', 'J', 'K', 'I', 'b', 'It sits exactly midway: G + 3 = J.', 'easy', '742a22825748c2ebd27027b7eac141aa');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: ADG, BEH, CFI, ?', 'DGJ', 'DGK', 'DGI', 'DGL', 'a', 'Every letter of a group moves forward by 1 in the next group.', 'hard', '6b97fc7c14246ee9a5fdc829a275008a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: AZ, BY, CX, ?', 'DV', 'DX', 'DY', 'DW', 'd', 'The first letter moves forward by 1 and the second moves backward by 1.', 'medium', '96c548073bd0cb62781ee066b72dcc96');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: EV, FU, GT, ?', 'HR', 'HT', 'HS', 'HU', 'c', 'The first letter moves forward by 1 and the second moves backward by 1.', 'medium', '76fca778d2329ddce3c98afcb8f56d3d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: IR, JQ, KP, ?', 'LQ', 'LO', 'LP', 'LN', 'b', 'The first letter moves forward by 1 and the second moves backward by 1.', 'medium', '4579619c0544708f3873d3361a52c610');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Which letter comes next? H, K, N, Q, ?', 'V', 'U', 'T', 'S', 'c', 'Each letter moves 3 place(s) forward in the alphabet.', 'easy', '8cc4e67fba1efeb2c17cc1a9c53913a8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Alphabet position', 'Which letter is 3 places to the left of D in the English alphabet?', 'Z', 'C', 'A', 'B', 'c', 'Count 3 letters backward from D.', 'easy', '634d14a987c51177a381532d7f4778c8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: ABD, BCE, CDF, ?', 'DEH', 'DEI', 'DEF', 'DEG', 'd', 'Every letter of a group moves forward by 1 in the next group.', 'hard', '97ea01d9c3cbc4ef4c74e542a270f666');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: ILO, JMP, KNQ, ?', 'LOT', 'LOS', 'LOQ', 'LOR', 'd', 'Every letter of a group moves forward by 1 in the next group.', 'hard', '93ca7c07484089e3004c2144d6d93604');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Alphabet position', 'Which letter is 5 places after M and 5 places before W?', 'S', 'Q', 'T', 'R', 'd', 'It sits exactly midway: M + 5 = R.', 'easy', '9fdfe61febf066f930587913bd89951b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Which letter comes next? B, E, H, K, ?', 'N', 'P', 'O', 'M', 'a', 'Each letter moves 3 place(s) forward in the alphabet.', 'easy', 'f29b17bd27c73e9aa47a5e658ac0776e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'letter-series', 'Letter patterns', 'Find the next group: BCE, CDF, DEG, ?', 'EFJ', 'EFG', 'EFI', 'EFH', 'd', 'Every letter of a group moves forward by 1 in the next group.', 'hard', '8d8f79abac3f1ad46a3ce1ea3f6350f1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Word substitution', 'In a code, \'table\' is called \'chair\', \'chair\' is called \'bed\', \'bed\' is called \'lamp\' and \'lamp\' is called \'shelf\'. On what does a person sleep?', 'chair', 'lamp', 'shelf', 'bed', 'b', 'A person sleeps on a bed, and \'bed\' is called \'lamp\' in this code.', 'medium', '0ef1ed96721af23d87310ca3952a465d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Word substitution', 'In a code, \'pen\' is called \'book\', \'book\' is called \'bag\', \'bag\' is called \'box\' and \'box\' is called \'pencil\'. What do students carry on their back?', 'pencil', 'book', 'box', 'bag', 'c', 'Students carry a bag; \'bag\' is called \'box\'.', 'medium', '145449787d9f6f2bde64960b37a94de7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Word substitution', 'In a code, \'red\' is called \'blue\', \'blue\' is called \'green\', \'green\' is called \'white\' and \'white\' is called \'black\'. What is the colour of milk?', 'black', 'green', 'blue', 'white', 'a', 'Milk is white; \'white\' is called \'black\'.', 'medium', 'd1de65dbe2d0964e642d50a7bba6b42e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Word substitution', 'In a code, \'sun\' is called \'moon\', \'moon\' is called \'star\', \'star\' is called \'cloud\' and \'cloud\' is called \'rain\'. What shines in the sky at midday?', 'sun', 'cloud', 'star', 'moon', 'd', 'The sun shines at midday; \'sun\' is called \'moon\'.', 'medium', 'ba1122ba855467e2d8a84f70172cd86f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Alphabet position codes', 'If A = 1, B = 2, C = 3 and so on, what is the sum of the letter values in the word TABLE?', '45', '43', '40', '41', 'c', 'T(20) + A(1) + B(2) + L(12) + E(5) = 40.', 'easy', '6d0865c06e2f2fa9f44b0d7a3ed8c525');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Letter shifting codes', 'In a code, A is replaced by Z, B by Y, C by X and so on. How is CHAIR written in that code?', 'YTASJ', 'XSZRI', 'WRYQH', 'RIAHC', 'b', 'Each letter is replaced by its mirror letter (A↔Z, B↔Y...).', 'hard', 'd605339b85ac57d3e358ea7cd671e696');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Letter shifting codes', 'In a certain code, PAPER is written as NYNCP. How is RIVER written in that code?', 'PGTCP', 'QHUDQ', 'OFSBO', 'TKXGT', 'a', 'Each letter is moved -2 place(s) backward.', 'medium', '4d11b82e1667be77635af155115fd70a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Letter shifting codes', 'In a certain code, RIVER is written as ULYHU. How is HOUSE written in that code?', 'ELRPB', 'LSYWI', 'KRXVH', 'JQWUG', 'c', 'Each letter is moved 3 place(s) forward.', 'medium', '6d48efbe89a117a2dbafaedbe61b8932');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Letter shifting codes', 'In a code, A is replaced by Z, B by Y, C by X and so on. How is PLANT written in that code?', 'TNALP', 'JNYLF', 'LPANH', 'KOZMG', 'd', 'Each letter is replaced by its mirror letter (A↔Z, B↔Y...).', 'hard', '8bbf51e318f3caa4bfc8e525c44ca77f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Alphabet position codes', 'If A = 1, B = 2, C = 3 and so on, what is the sum of the letter values in the word HOUSE?', '73', '68', '72', '65', 'b', 'H(8) + O(15) + U(21) + S(19) + E(5) = 68.', 'easy', 'de6266236448884aaea2b161ac9842e7');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Letter shifting codes', 'In a certain code, HOUSE is written as JQWUG. How is RIVER written in that code?', 'PGTCP', 'ULYHU', 'TKXGT', 'SJWFS', 'c', 'Each letter is moved 2 place(s) forward.', 'medium', '31ea3c4c5f3f4cf31eb606a6a8372d3c');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'coding-decoding', 'Letter shifting codes', 'In a code, A is replaced by Z, B by Y, C by X and so on. How is TABLE written in that code?', 'GZYOV', 'ELBAT', 'HAZPW', 'FYXNU', 'a', 'Each letter is replaced by its mirror letter (A↔Z, B↔Y...).', 'hard', '40b9d4f302823a460de08894f777932f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Direct relations', 'Pointing to a photograph, Meera says, \'He is the son of my mother\'s only brother.\' How is the man related to Meera?', 'Nephew', 'Uncle', 'Brother', 'Cousin', 'd', 'Mother\'s brother is Meera\'s maternal uncle; his son is her cousin.', 'easy', '6080de0e4680f1979b8bc104d353a13d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'A is the brother of B. B is the sister of C. C is the father of D. How is A related to D?', 'Uncle', 'Brother', 'Grandfather', 'Father', 'a', 'A and C are siblings, so A is the brother of D\'s father, i.e. D\'s uncle.', 'medium', '0bb6649723a6af2711121b1494d43bf3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Direct relations', 'Rohan\'s mother is the only daughter of Arjun. How is Arjun related to Rohan?', 'Uncle', 'Paternal grandfather', 'Father', 'Maternal grandfather', 'd', 'Arjun is the father of Rohan\'s mother.', 'easy', 'd09c82ecc59b4dee8dc958a53183256b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'Pointing to a woman, Vikram says, \'Her son is the husband of my sister.\' How is the woman related to Vikram\'s sister?', 'Grandmother', 'Aunt', 'Mother-in-law', 'Sister-in-law', 'c', 'The woman is the mother of the sister\'s husband.', 'medium', '6d7fef697260cb0b4f625454464aca47');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Direct relations', 'X is the father of Y and Y is the mother of Z. How is X related to Z?', 'Paternal grandfather', 'Maternal grandfather', 'Father', 'Uncle', 'b', 'X is the father of Z\'s mother.', 'easy', '3f74782a031f14e70bcbe8a3a45da837');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'Anil introduces Sunita as the daughter of the sister of his mother. How is Sunita related to Anil?', 'Sister', 'Aunt', 'Cousin', 'Niece', 'c', 'Mother\'s sister is Anil\'s aunt; her daughter is his cousin.', 'medium', '99ee85f43bcb1e31755deb8d425eba9e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'Ravi tells Mohan, \'Your mother is the only daughter of my mother.\' How is Ravi related to Mohan?', 'Maternal uncle', 'Brother', 'Father', 'Cousin', 'a', 'Ravi\'s sister is Mohan\'s mother, so Ravi is Mohan\'s maternal uncle.', 'hard', 'bbbb966109e33da4df965e5a2086386a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'Pointing to a boy, Tina says, \'He is the son of the only child of my grandfather.\' How is the boy related to Tina?', 'Brother', 'Uncle', 'Cousin', 'Nephew', 'a', 'The grandfather\'s only child is Tina\'s parent, so that parent\'s son is Tina\'s brother.', 'hard', 'ea7d69f44f1d1cb58bc49e7c97b83f58');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'A is B\'s sister. C is B\'s mother. D is C\'s father. How is A related to D?', 'Granddaughter', 'Sister', 'Niece', 'Daughter', 'a', 'C is also A\'s mother, so D is A\'s maternal grandfather and A is his granddaughter.', 'medium', 'e01bec1c89f9b8078565b5f681721dfc');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'Pointing to a man, a woman says, \'He is the brother of the father of my son.\' How is the man related to the woman?', 'Brother', 'Cousin', 'Uncle', 'Brother-in-law', 'd', 'The father of her son is her husband; his brother is her brother-in-law.', 'medium', '233c444186b243b043a11cdff9bf9e4f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'A\'s mother is B\'s sister and B\'s daughter is C. How is C related to A?', 'Cousin', 'Sister', 'Niece', 'Aunt', 'a', 'A\'s mother and B are siblings, so A and B\'s daughter C are cousins.', 'medium', 'a8480a2344bbc51671a81b56b6930ebb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'blood-relations', 'Relation chains', 'Nina is the daughter of Om. Om\'s brother is Piyush and Piyush\'s wife is Rita. How is Nina related to Rita?', 'Cousin', 'Daughter', 'Sister-in-law', 'Niece', 'd', 'Rita is the wife of Nina\'s father\'s brother, so Rita is Nina\'s aunt and Nina is her niece.', 'medium', '9236c14ace66f8de0a1620ffbac51170');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A man walks 12 km north, then 8 km east and then 6 km south. How far is he from his starting point?', '14 km', '10 km', '13 km', '11 km', 'b', 'Net north = 12 - 6 = 6 km; east = 8 km; distance = √(6² + 8²) = 10 km.', 'medium', '8f96d2699a8b134c986a3c40e1b85aa1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A man walks 7 km north, then 12 km east and then 2 km south. How far is he from his starting point?', '8 km', '10 km', '13 km', '16 km', 'c', 'Net north = 7 - 2 = 5 km; east = 12 km; distance = √(5² + 12²) = 13 km.', 'medium', '82c87ede230a46803e1f646858c34f3a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A boy walks 8 km south and then 8 km east. In which direction is he from his starting point?', 'North-East', 'South-East', 'South-West', 'North-West', 'b', 'Equal distances south and east put him exactly south-east of the start.', 'medium', '0c38666e1c56cc5cc734eb5be54747b3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A boy walks 5 km north and then 5 km west. In which direction is he from his starting point?', 'North-West', 'South-West', 'North-East', 'South-East', 'a', 'Equal distances north and west put him exactly north-west of the start.', 'medium', '01e69b5869f20d789a96303bfa3287cf');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A man walks 8 km north, then 8 km east and then 2 km south. How far is he from his starting point?', '13 km', '11 km', '10 km', '12 km', 'c', 'Net north = 8 - 2 = 6 km; east = 8 km; distance = √(6² + 8²) = 10 km.', 'medium', '786c41eb431e71aa88debbcd174412e2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A boy walks 11 km north and then 11 km west. In which direction is he from his starting point?', 'North-East', 'North-West', 'South-West', 'South-East', 'b', 'Equal distances north and west put him exactly north-west of the start.', 'medium', '2e3955bd36d9f352d8c50f8b0ea50308');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A boy walks 12 km south and then 12 km east. In which direction is he from his starting point?', 'South-East', 'North-West', 'North-East', 'South-West', 'a', 'Equal distances south and east put him exactly south-east of the start.', 'medium', '08c1b32f0640e02f8d473e8d0196208b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'Priya walks 6 km south, turns left and walks 5 km, then turns left again and walks 6 km. How far is she from the starting point?', '8 km', '5 km', '2 km', '3 km', 'b', 'After two turns in the same direction she has walked 6 km out and 6 km back, so only the 5 km sideways leg separates her from the start.', 'hard', '7a2775c4d08239e08eb560403f2a3172');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Turns and facing', 'Sameer is facing south. He turns right, then left, then right. Which direction is he facing now?', 'East', 'West', 'North', 'South', 'b', 'Each right turn is a 90° clockwise turn and each left turn is 90° anticlockwise.', 'medium', '1869d19b30245768676108a6be02a3df');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A boy walks 7 km north and then 7 km east. In which direction is he from his starting point?', 'South-East', 'North-West', 'North-East', 'South-West', 'c', 'Equal distances north and east put him exactly north-east of the start.', 'medium', '9904fce929ccb09e5c48d1ac536d40cb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A man walks 9 km north, then 15 km east and then 1 km south. How far is he from his starting point?', '19 km', '13 km', '22 km', '17 km', 'd', 'Net north = 9 - 1 = 8 km; east = 15 km; distance = √(8² + 15²) = 17 km.', 'medium', 'a09cfa454e903603dd9eea208bef6f15');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'direction-sense', 'Distance and displacement', 'A boy walks 8 km north and then 8 km east. In which direction is he from his starting point?', 'South-West', 'North-East', 'South-East', 'North-West', 'b', 'Equal distances north and east put him exactly north-east of the start.', 'medium', '70ba377f36f37bc626f39bf891f07157');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: Some towers are roads. Some roads are bridges.\nConclusions: I. No bridges are roads.  II. Some bridges are roads.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'b', 'Checking every Venn arrangement that fits the statements: Conclusion I does not follow and Conclusion II follows.', 'hard', '12e0787cfd8953d5a242ee4528c43d25');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: All keys are doors. Some doors are not clocks.\nConclusions: I. Some keys are not clocks.  II. No keys are doors.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'd', 'Checking every Venn arrangement that fits the statements: Conclusion I does not follow and Conclusion II does not follow.', 'hard', '7679a1b24e5d6a29e6b01417a0560255');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: No keys are doors. Some doors are not clocks.\nConclusions: I. All doors are keys.  II. Some clocks are keys.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'd', 'Checking every Venn arrangement that fits the statements: Conclusion I does not follow and Conclusion II does not follow.', 'hard', 'f616738978ec0a05f56d9a5aa7da6e8e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: Some spoons are cups. No cups are plates.\nConclusions: I. No plates are cups.  II. All cups are plates.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Checking every Venn arrangement that fits the statements: Conclusion I follows and Conclusion II does not follow.', 'hard', 'a2a629862539d76905e5ab6d4505ef4f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: Some boxes are not pens. Some pens are not books.\nConclusions: I. No boxes are pens.  II. Some boxes are pens.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'd', 'Checking every Venn arrangement that fits the statements: Conclusion I does not follow and Conclusion II does not follow.', 'hard', '2a534b582229c9da8d2c6c697ec934c5');
