INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: All lamps are chairs. No chairs are roses.\nConclusions: I. No roses are lamps.  II. Some lamps are roses.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Checking every Venn arrangement that fits the statements: Conclusion I follows and Conclusion II does not follow.', 'hard', '9169762042df0a3e8c54e2eb22b858c1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: Some roses are not lamps. All lamps are chairs.\nConclusions: I. No lamps are roses.  II. No roses are lamps.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'd', 'Checking every Venn arrangement that fits the statements: Conclusion I does not follow and Conclusion II does not follow.', 'hard', '80af56f2bef97d453cd75cac5f471457');
