INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: No pens are books. Some books are not boxes.\nConclusions: I. Some books are not pens.  II. No boxes are books.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Checking every Venn arrangement that fits the statements: Conclusion I follows and Conclusion II does not follow.', 'hard', '6039c5cdc7d967ef31f03c511fced447');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: All keys are doors. All doors are clocks.\nConclusions: I. Some clocks are keys.  II. All clocks are keys.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Checking every Venn arrangement that fits the statements: Conclusion I follows and Conclusion II does not follow.', 'medium', '039374c735a523559635ed3ec932f8fe');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'syllogism', 'Two-premise syllogisms', 'Statements: No doors are keys. Some keys are not clocks.\nConclusions: I. Some keys are clocks.  II. No keys are doors.\n(Take each group named as having at least one member.)', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'b', 'Checking every Venn arrangement that fits the statements: Conclusion I does not follow and Conclusion II follows.', 'hard', '386ce487e59fbc0e888ca25fd8ea4206');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Row arrangement puzzles', 'Five friends A, B, C, D and E sit in a row facing north. E sits at one of the two ends. A sits exactly in the middle. C does not sit next to A. B sits somewhere to the left of D. Who sits immediately to the right of A?', 'D', 'B', 'C', 'A', 'a', 'Place the fixed positions first, then use the remaining conditions to eliminate options.', 'hard', 'dda0f51026e7113ddf528e8a4a67778f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Row arrangement puzzles', 'A, B, C, D and E sit in a row facing north. B sits at the extreme left. D sits immediately next to B. C sits at the extreme right. A is not next to C. Who sits in the middle?', 'D', 'A', 'B', 'C', 'b', 'Place the fixed positions first, then use the remaining conditions to eliminate options.', 'hard', '3f6be76baee93f18821e01477fee4573');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Row arrangement puzzles', 'Five people A, B, C, D and E stand in a queue. C is third from the front. A is directly behind C. B is somewhere ahead of E. D is at the very front. Who is at the very back?', 'B', 'E', 'A', 'C', 'b', 'Place the fixed positions first, then use the remaining conditions to eliminate options.', 'hard', 'af869be4893816f2f421703e00ba14fb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row, A is 15th from the left and B is 10th from the right. After they exchange places, A becomes 10th from the left. How many people are in the row?', '22', '20', '19', '18', 'c', 'After the exchange A stands where B stood, so B was 10th from the left and 10th from the right; total = 10 + 10 - 1 = 19.', 'hard', '5a29e437353ed15b5f577973632bd2a9');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row, Aarav is 7th from the left end and 13th from the right end. How many people are in the row?', '14', '16', '21', '19', 'd', 'Total = 7 + 13 - 1 = 19.', 'easy', '99c3d839efcafd383369940131b94a7b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row, Aarav is 9th from the left end and 13th from the right end. How many people are in the row?', '21', '18', '17', '25', 'a', 'Total = 9 + 13 - 1 = 21.', 'easy', '0dcc0e0794eaf6fe3918ca54578985b5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row of 33 students, Kavya\'s position from the left is 5. What is her position from the right?', '26', '29', '28', '34', 'b', '33 - 5 + 1 = 29.', 'easy', '1e514170b7d0b65490b7b3e621cc0162');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row of 32 students, Dev is 7th from the left and Esha is 5th from the right. How many students stand between them?', '16', '15', '21', '20', 'd', 'Esha is 32 - 5 + 1 = 28th from the left; students between = 28 - 7 - 1 = 20.', 'medium', 'f608e2e61f3b1cf45b2b2b3988111042');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row, A is 18th from the left and B is 7th from the right. After they exchange places, A becomes 11th from the left. How many people are in the row?', '17', '16', '18', '21', 'a', 'After the exchange A stands where B stood, so B was 11th from the left and 7th from the right; total = 11 + 7 - 1 = 17.', 'hard', '8c6ee13e55ce0b9df7747e9e8f259668');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Circular arrangements', '10 people sit around a circular table at equal gaps and are numbered 1 to 10 in clockwise order. Who sits directly opposite person 8?', '6', '3', '13', '2', 'b', 'The person opposite is 5 seats away: (8 + 5) counted within 1-10.', 'medium', 'e00c5316633abf0b162e547c1150701a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row, A is 15th from the left and B is 13th from the right. After they exchange places, A becomes 13th from the left. How many people are in the row?', '25', '28', '27', '23', 'a', 'After the exchange A stands where B stood, so B was 13th from the left and 13th from the right; total = 13 + 13 - 1 = 25.', 'hard', '41d2002614cf993fc6d8332d81f1c0e0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'seating-arrangement', 'Positions in a row', 'In a row of 38 students, Dev is 11th from the left and Esha is 5th from the right. How many students stand between them?', '22', '26', '24', '20', 'a', 'Esha is 38 - 5 + 1 = 34th from the left; students between = 34 - 11 - 1 = 22.', 'medium', '429c168fd11d50495b1a7c25c193ae17');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Set relationships', 'Which diagram best represents the relationship between Doctors, Surgeons and Humans?', 'Doctors and Surgeons as two overlapping circles outside Humans', 'A circle for Surgeons inside a circle for Doctors, both inside a larger circle for Humans', 'Three separate circles', 'Humans inside Surgeons inside Doctors', 'b', 'Every surgeon is a doctor and every doctor is a human, so the sets are nested.', 'medium', '64b8681df0ff341ccae1e2bdbc69dfa6');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Set relationships', 'Which diagram best represents Cats, Dogs and Animals?', 'Cats and Dogs as two separate circles, both inside a larger circle for Animals', 'Animals inside Cats, Cats inside Dogs', 'Cats and Dogs overlapping inside Animals', 'Three overlapping circles of equal size', 'a', 'Cats and dogs are different animals, so they do not overlap, but both belong to Animals.', 'medium', 'a19ed52e6aa87bd61d0a864628fb048e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Set relationships', 'Which diagram best represents Teachers, Women and Doctors?', 'Three separate circles', 'Three circles overlapping each other partially', 'Teachers inside Women inside Doctors', 'Women and Doctors separate, Teachers containing both', 'b', 'A person can be a teacher, a woman and a doctor, but none of the sets contains another.', 'medium', 'f3830f9ea3cd6fcecd3e26eb0d23aeec');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Set relationships', 'Which diagram best represents Pens, Stationery and Erasers?', 'Three separate circles', 'Pens and Erasers as two separate circles inside a larger circle for Stationery', 'Pens inside Erasers inside Stationery', 'Pens and Erasers overlapping outside Stationery', 'b', 'Pens and erasers are different objects that both belong to stationery.', 'medium', 'e5e4b0611fc473dc21f494aad1768b5b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Two-set problems', 'In a class of 60 students, 22 study French and 28 study German. 9 study both. How many study exactly one of the two languages?', '35', '32', '30', '33', 'b', 'Exactly one = (22 - 9) + (28 - 9) = 32.', 'medium', '30fabb121bb799d36b0854b3dfcf4d1b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Two-set problems', 'Every student in a class of 50 plays cricket or football. 45 play cricket and 47 play football. How many play both?', '39', '44', '42', '43', 'c', 'Both = 45 + 47 - 50 = 42.', 'medium', '6ffea84ac0c06077efcd941983663f78');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Two-set problems', 'In a group of 100 people, 36 like tea, 30 like coffee and 11 like both. How many like neither?', '41', '50', '49', '45', 'd', 'Either = 36 + 30 - 11 = 55; neither = 100 - 55.', 'easy', '863b862a3ea3c2493936f93e46a3265d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Three-set problems', 'In a survey, n(A) = 36, n(B) = 50, n(C) = 32, n(A∩B) = 15, n(B∩C) = 11, n(A∩C) = 14 and n(A∩B∩C) = 6. Find n(A∪B∪C).', '81', '84', '83', '86', 'b', '36 + 50 + 32 - 15 - 11 - 14 + 6 = 84.', 'hard', 'dee7570e80de3bbeac0619d901d6894f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Three-set problems', 'In a survey, n(A) = 41, n(B) = 50, n(C) = 40, n(A∩B) = 14, n(B∩C) = 13, n(A∩C) = 9 and n(A∩B∩C) = 6. Find n(A∪B∪C).', '104', '97', '101', '103', 'c', '41 + 50 + 40 - 14 - 13 - 9 + 6 = 101.', 'hard', 'fc35f47b1a7d3705ed31d29cca963ce5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Two-set problems', 'In a group of 80 people, 31 like tea, 46 like coffee and 13 like both. How many like neither?', '16', '20', '11', '18', 'a', 'Either = 31 + 46 - 13 = 64; neither = 80 - 64.', 'easy', '76c23eaef2e381191f86c3e1914fbdcb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Two-set problems', 'In a class of 100 students, 28 study French and 34 study German. 10 study both. How many study exactly one of the two languages?', '46', '38', '42', '41', 'c', 'Exactly one = (28 - 10) + (34 - 10) = 42.', 'medium', 'f58a142d383285009f6293e1dcad0088');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'venn-diagrams', 'Three-set problems', 'In a survey, n(A) = 47, n(B) = 48, n(C) = 33, n(A∩B) = 12, n(B∩C) = 8, n(A∩C) = 11 and n(A∩B∩C) = 6. Find n(A∪B∪C).', '98', '99', '103', '106', 'c', '47 + 48 + 33 - 12 - 8 - 11 + 6 = 103.', 'hard', '5db960a41d870e72882242b8ee2c037b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: All the flats in Green Court have a balcony. Some flats in Green Court are rented out.\nConclusions: I. Some rented flats have a balcony.  II. All flats with a balcony are in Green Court.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Rented flats in Green Court have balconies, but balconies may exist elsewhere too.', 'medium', 'bdc5da8c86f7be135fb96877f172a918');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: Only members can enter the club after 8 p.m. Ritu entered the club at 9 p.m.\nConclusions: I. Ritu is a member.  II. Ritu is a manager of the club.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Only members enter after 8 p.m., so Ritu must be a member; nothing says she is a manager.', 'medium', 'aeb60412a7deb5434654d6945cb22be8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: The price of petrol has been increased by 10%.\nConclusions: I. Transport costs may rise.  II. All people will stop using vehicles.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'Higher fuel prices can raise transport costs, but a total stop is an extreme claim.', 'easy', 'bb12d986ce876b7c94508ebc0b0606b8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: Some books are magazines. No magazine is a newspaper.\nConclusions: I. Some books are not newspapers.  II. No book is a newspaper.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'The books that are magazines are not newspapers; other books are not covered.', 'medium', '3701742cb7471d4e62ec4dc2e5e81f21');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: Every student who passes the screening test is called for an interview. Neha was not called for an interview.\nConclusions: I. Neha did not pass the screening test.  II. Neha did not appear for the screening test.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'If she had passed she would have been called; she may have appeared and failed.', 'hard', 'b7cc73abb2bf66b5ec5bb8e4c337492c');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: A hospital notice says: \'Visitors are allowed only between 4 p.m. and 6 p.m.\'\nConclusions: I. A visitor who arrives at 5 p.m. may meet patients.  II. A visitor who arrives at 7 p.m. may not meet patients.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'c', '5 p.m. is inside the allowed window and 7 p.m. is outside it.', 'medium', 'dcfc3ec1895c2f6eebc3c558906efa80');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: Most of the shops in Market Street are closed on Sundays.\nConclusions: I. All shops in Market Street are closed on Sundays.  II. Some shops in Market Street are closed on Sundays.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'b', '\'Most\' means more than half, so some are closed, but not necessarily all.', 'medium', '4620ff517483f5c125e7991f60a3d99d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: No student of Class X may use a mobile phone in school.\nConclusions: I. Ankit, a Class X student, may bring a phone and use it in school.  II. Ankit, a Class X student, may not use a phone in school.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'b', 'The rule bans use in school for every Class X student, including Ankit.', 'easy', '2ad8e0bb83e785e113bdec06bf15dce0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: Either the 7:30 bus or the 8:00 bus will get you to the station on time.\nConclusions: I. If you miss the 7:30 bus, the 8:00 bus will still get you there on time.  II. You can reach on time only by the 8:00 bus.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'The statement offers two working options, so the 7:30 bus also works.', 'medium', '10c1c2f0bd47718f4d0a5236fa79bdd2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: A new metro line will open in the city next year.\nConclusions: I. All buses in the city will stop running.  II. Everyone in the city will travel by metro.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'd', 'Nothing in the statement suggests buses will stop or that everybody will switch.', 'easy', 'ee286123eb270564608a837d9302a208');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: Only graduates are eligible for the post. Mira is eligible for the post.\nConclusions: I. Mira is a graduate.  II. A non-graduate is not eligible for the post.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'c', 'Eligibility is limited to graduates, so both conclusions follow.', 'medium', '4abcb06974e7f91243aecb7c27964f80');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'statements-conclusions', 'Statement and conclusions', 'Statement: The city council has banned plastic bags in all markets.\nConclusions: I. Shoppers in the markets will need alternatives to plastic bags.  II. Plastic bags will no longer be produced anywhere in the country.', 'Only conclusion I follows', 'Only conclusion II follows', 'Both I and II follow', 'Neither I nor II follows', 'a', 'The ban covers markets only, not production across the country.', 'easy', 'c5fe20fe9a594791f327229dfc135f64');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What is the price of one notebook?\nI. Five notebooks cost Rs. 250.\nII. A pen costs Rs. 10 less than a notebook.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'a', 'Statement I gives 250 ÷ 5 = Rs. 50; statement II mentions the pen\'s price, not the notebook\'s.', 'easy', '2da77dfaf037705131678606f48ec8d0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What is Sita\'s age?\nI. Sita is 4 years older than her brother.\nII. Her brother is 12 years old.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'c', 'Only by combining both statements: 12 + 4 = 16.', 'easy', 'fe7e57936d035b91456efebd735d4413');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'Is the number x even?\nI. x is divisible by 4.\nII. x is a multiple of 3.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'a', 'Every multiple of 4 is even; a multiple of 3 can be odd or even.', 'medium', 'e65ec351e0707eafcf61c710ebb44729');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What is the area of a rectangle?\nI. Its perimeter is 30 cm.\nII. Its length is 10 cm.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'c', 'Together: width = 15 - 10 = 5 cm, so area = 50 cm².', 'medium', 'd770816ee3c426cfd7a40ecf2534ce81');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What was the cost price of a bag?\nI. The shopkeeper made some profit on the bag.\nII. The bag was sold for Rs. 600 at a 20% profit.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'b', 'Statement II gives CP = 600 ÷ 1.2 = Rs. 500; statement I has no numbers.', 'medium', '890b42e7dac1d25422f820ca1995fb4b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'Who is taller, Amit or Bala?\nI. Amit is taller than Chetan.\nII. Chetan is taller than Bala.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'c', 'Together: Amit > Chetan > Bala.', 'easy', '5996f632325d2a6919316d951b35875e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What is the value of y?\nI. y + 3 = 10.\nII. y² = 49.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'a', 'Statement I gives y = 7; statement II allows y = 7 or -7.', 'medium', '83201d61058cb93fbffbfd059890d092');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'Is Kiran older than Ravi?\nI. Kiran was born in 1998.\nII. Ravi is 25 years old.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'd', 'Without knowing the current year, Ravi\'s birth year cannot be found.', 'hard', '80bb9ee1285f99c704aea50a00e0edeb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'How many pages does the book have?\nI. Riya reads 20 pages every day and finishes the book in exactly 15 days.\nII. The book has more than 200 pages.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'a', 'Statement I gives 20 × 15 = 300 pages; statement II gives only a range.', 'medium', '440d3167fc50ed8b20944e2e47905ed4');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What is the length of a train?\nI. It crosses a pole in 12 seconds.\nII. Its speed is 54 km/h.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'c', 'Speed 15 m/s × 12 s = 180 m needs both statements.', 'hard', '726db5cf1dbb374595eada1400f1068d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'What is the perimeter of a square?\nI. All four sides of the square are equal.\nII. The area of the square is 64 cm².', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'b', 'Statement II gives side 8 cm, so perimeter 32 cm; statement I is true for every square.', 'medium', 'c036432f5c47dd8d1b44cf58d1f7283b');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'data-sufficiency', 'Sufficiency of information', 'Is the number N a prime number?\nI. N is greater than 10.\nII. N is odd.', 'Statement I alone is sufficient', 'Statement II alone is sufficient', 'Both statements together are needed; neither alone is enough', 'Even both statements together are not sufficient', 'd', '11 is prime and 15 is not; both fit the statements.', 'hard', 'cdc1b11cd9c3800d5850cf88f314e1ac');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Calendar puzzles', 'Today is Wednesday. What day of the week will it be after 100 days?', 'Sunday', 'Friday', 'Saturday', 'Thursday', 'b', '100 = 7 × 14 + 2, so the day moves 2 step(s) forward from Wednesday.', 'medium', '908ea5e48f627162b8ad154ef30791fe');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Calendar puzzles', 'Today is Friday. What day of the week will it be after 45 days?', 'Wednesday', 'Sunday', 'Tuesday', 'Monday', 'd', '45 = 7 × 6 + 3, so the day moves 3 step(s) forward from Friday.', 'medium', '9e22965a4762be2c427950bc1f104c16');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Calendar puzzles', 'Today is Sunday. What day of the week will it be after 150 days?', 'Friday', 'Thursday', 'Tuesday', 'Wednesday', 'd', '150 = 7 × 21 + 3, so the day moves 3 step(s) forward from Sunday.', 'medium', '39a6d1b86d987afb20c918b553cd675a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Calendar puzzles', 'Today is Tuesday. What day of the week will it be after 61 days?', 'Saturday', 'Tuesday', 'Monday', 'Sunday', 'd', '61 = 7 × 8 + 5, so the day moves 5 step(s) forward from Tuesday.', 'medium', '066297bc94b41d67d365f78b8aa4d6b6');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'A patch of lily pads doubles in size every day and covers the whole pond on day 30. On which day did it cover half the pond?', 'Day 29', 'Day 15', 'Day 28', 'Day 25', 'a', 'Doubling once more (day 29 → day 30) fills the pond, so half was covered on day 29.', 'medium', 'e44da8c883d7d0734aa930440f46db6e');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'If 5 machines take 5 minutes to make 5 toys, how many minutes do 100 machines need to make 100 toys?', '1 minute', '100 minutes', '5 minutes', '20 minutes', 'c', 'Each machine makes one toy in 5 minutes, so 100 machines make 100 toys in 5 minutes.', 'hard', '0a56857c6299a0b6d56d0eb1737bb9e9');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'A clock strikes once at 1 o\'clock, twice at 2 o\'clock and so on up to 12 times at 12 o\'clock. How many strikes are there from 1 o\'clock to 12 o\'clock?', '78', '144', '72', '66', 'a', '1 + 2 + ... + 12 = 12 × 13 / 2 = 78.', 'medium', '455d8eabc296b7708e8cd32bccf302e3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'How many squares of all sizes are there on a 3 × 3 grid of small squares?', '16', '14', '9', '13', 'b', '9 small (1×1) + 4 of size 2×2 + 1 of size 3×3 = 14.', 'hard', 'c5abcee3f9ada972086d0df9eb3618fb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'P is taller than Q. Q is taller than R. S is shorter than R. T is taller than P. Who is the shortest?', 'Q', 'S', 'T', 'R', 'b', 'The order is T > P > Q > R > S, so S is the shortest.', 'easy', 'ba50fa35890318dbb08d5d81a4bbd2e8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'A father is three times as old as his son. After 12 years he will be twice as old as his son. How old is the son now?', '15 years', '6 years', '10 years', '12 years', 'd', '3x + 12 = 2(x + 12) gives x = 12.', 'medium', 'b8a1874de0d7421a69aba3da309cff30');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'A 20-metre ribbon is cut into pieces of 2 metres each. How many cuts are needed?', '11', '8', '10', '9', 'd', 'There are 10 pieces, and n pieces need n - 1 cuts.', 'easy', 'b55a423097240b367c7b2ac986f10304');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'Nine coins look identical, but one is slightly heavier. What is the minimum number of weighings on a balance scale that is guaranteed to find it?', '2', '1', '4', '3', 'a', 'Weigh 3 against 3 to find the group holding the heavy coin, then weigh two coins from that group.', 'hard', '37a8c3ce2b94e0ffad9663bf51f0d6f6');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Logical Reasoning', 'logical-puzzles', 'Classic puzzles', 'A bat and a ball together cost Rs. 110. The bat costs Rs. 100 more than the ball. What does the ball cost?', 'Rs. 1', 'Rs. 10', 'Rs. 5', 'Rs. 15', 'c', 'Ball + (ball + 100) = 110, so the ball costs Rs. 5.', 'hard', 'd903078877b6b211f243f2d8e6c5f792');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'One-word substitution', 'Which one word means \'a person who loves books\'?', 'Philanthropist', 'Egotist', 'Misanthrope', 'Bibliophile', 'd', '\'Biblio\' relates to books.', 'easy', 'd01a860925f6a4d6e442d56a9cdf4fd5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'One-word substitution', 'Which word describes \'a government in which one ruler holds absolute power\'?', 'Theocracy', 'Autocracy', 'Democracy', 'Aristocracy', 'b', 'Autocracy means rule by a single person with unlimited power.', 'medium', 'ce0a1264aae5830cea92ea6ae56cb98a');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Word meanings', 'Choose the correct meaning of \'meticulous\'.', 'Lazy', 'Very careful about details', 'Careless', 'Noisy', 'b', 'A meticulous person pays close attention to detail.', 'medium', '5486ab71f568894e45ec4217aefa7269');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Word meanings', 'Choose the correct meaning of \'ephemeral\'.', 'Lasting for a very short time', 'Fragile', 'Harmful', 'Eternal', 'a', 'Ephemeral things last only briefly.', 'hard', '83221df7e78e6b52969e9217bb50e1d2');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Word meanings', 'Choose the correct meaning of \'reluctant\'.', 'Tired', 'Curious', 'Eager', 'Unwilling', 'd', 'Reluctant means not willing to do something.', 'easy', 'e860c1904890a2bec568860b7ea52c8c');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Idioms and phrases', 'What does the idiom \'to break the ice\' mean?', 'To feel very cold', 'To end a friendship', 'To damage something', 'To start a conversation in an awkward situation', 'd', 'It means to ease the tension when people first meet.', 'easy', '3b715d9f523b9506d22d0d1cf14be0cb');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Idioms and phrases', 'What does the idiom \'a piece of cake\' mean?', 'A sweet dessert', 'Something very easy', 'A rare chance', 'A small gift', 'b', 'It describes a task that is effortless.', 'easy', '9d540b5e73bf5f7f1d43f399ac6fbb7d');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Idioms and phrases', 'What does the idiom \'once in a blue moon\' mean?', 'Every month', 'Very rarely', 'Never', 'Only at night', 'b', 'It refers to something that happens extremely seldom.', 'medium', '9320419f44c8c9b085ca5d4c469f11b0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Word meanings', 'Choose the correct meaning of \'verbose\'.', 'Rude', 'Silent', 'Honest', 'Using more words than necessary', 'd', 'Verbose speech or writing is wordy.', 'medium', '25bc1257f7c3592d8e71c6149490a987');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Word meanings', 'Choose the correct meaning of \'frugal\'.', 'Wealthy', 'Generous', 'Wasteful', 'Careful about spending money', 'd', 'A frugal person avoids unnecessary expense.', 'medium', '85e485b77bf35039252480018ae8de97');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'Word meanings', 'Choose the correct meaning of \'candid\'.', 'Honest and direct', 'Shy', 'Secretive', 'Angry', 'a', 'A candid answer is frank and open.', 'medium', '67cbb5f399da357d9257e8f17c6d2108');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'vocabulary', 'One-word substitution', 'Which one word means \'a person who is new to a subject or activity\'?', 'Novice', 'Mentor', 'Veteran', 'Expert', 'a', 'A novice is a beginner.', 'easy', 'dfffbd16a6752c04ad792d6b58f4e997');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'synonyms', 'Word pairs', 'Choose the word closest in meaning to \'Abundant\'.', 'Scarce', 'Costly', 'Plentiful', 'Tiny', 'c', '\'Abundant\' and \'Plentiful\' mean nearly the same thing.', 'medium', 'adedaad13f476d1a3e00f6dfa7c3ff54');
