INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'sentence-completion', 'Context clues', 'Choose the word that best completes the sentence:\nBecause the road was flooded, the villagers were ______ from the town for three days.', 'rewarded', 'isolated', 'attracted', 'invited', 'b', 'Flooded roads cut people off.', 'medium', '3e95a820e86ef5654b7f8a39ae11c330');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'sentence-completion', 'Context clues', 'Choose the word that best completes the sentence:\nAlthough he was tired, he was ______ to finish the work before leaving.', 'reluctant', 'determined', 'forgetful', 'unable', 'b', '\'Although\' introduces contrast with being tired.', 'medium', '2bbad2444fa743aafd21c44e0a0625a1');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'sentence-completion', 'Context clues', 'Choose the word that best completes the sentence:\nThe scientist\'s theory was ______ by many experiments over the years.', 'forgotten', 'supported', 'hidden', 'ignored', 'b', 'Experiments can support a theory.', 'medium', 'bf6a82703cd204a93ad612a00a541c4f');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'sentence-completion', 'Context clues', 'Choose the word that best completes the sentence:\nThe shop offers a ______ discount during the festival, so prices are much lower.', 'negligible', 'invisible', 'substantial', 'tiny', 'c', '\'Much lower\' suggests a large discount.', 'medium', 'e84a459ed149addb72f4a91c64851408');
