INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Many cities now face water shortages because their populations are growing faster than their water supplies. Experts say that fixing leaking pipes, collecting rainwater and reusing treated water can save millions of litres every year. However, these steps only work when people also change their habits, such as turning off taps and avoiding waste.\n\nQuestion: What is the main idea of the passage?', 'Cities can reduce water shortages through better systems and careful habits', 'Leaking pipes are harmless', 'Populations should stop growing', 'Rainwater is unsafe to use', 'a', 'The passage combines technical fixes with changes in behaviour.', 'medium', 'c6edd828a14ac54e13e425ad73581df5');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Many cities now face water shortages because their populations are growing faster than their water supplies. Experts say that fixing leaking pipes, collecting rainwater and reusing treated water can save millions of litres every year. However, these steps only work when people also change their habits, such as turning off taps and avoiding waste.\n\nQuestion: Which step is mentioned as a way to save water?', 'Collecting rainwater', 'Building more roads', 'Importing bottled water', 'Digging deeper wells only', 'a', 'Rainwater collection is listed among the steps.', 'easy', '2899e959e94d7445f7b76f8835d031b0');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Many cities now face water shortages because their populations are growing faster than their water supplies. Experts say that fixing leaking pipes, collecting rainwater and reusing treated water can save millions of litres every year. However, these steps only work when people also change their habits, such as turning off taps and avoiding waste.\n\nQuestion: Why do the technical steps also need changes in people\'s habits?', 'Experts disagree with each other', 'Pipes cannot be repaired', 'Treated water is expensive', 'Systems alone cannot solve the problem if people keep wasting water', 'd', 'The passage says the steps only work along with habit change.', 'medium', '417badab74f0e8944028e1f57581f389');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: A survey of students found that those who read for even twenty minutes a day had a richer vocabulary and wrote clearer essays. The researchers noted that the type of reading did not matter as much as the regular habit. Students who read only before exams showed little improvement.\n\nQuestion: According to the researchers, what matters most?', 'Reading before exams', 'Reading for several hours', 'Reading regularly', 'Reading only difficult books', 'c', 'They said the regular habit mattered more than the type of reading.', 'easy', '3a2eff86634a73b30a1ab12bb7108f01');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: A survey of students found that those who read for even twenty minutes a day had a richer vocabulary and wrote clearer essays. The researchers noted that the type of reading did not matter as much as the regular habit. Students who read only before exams showed little improvement.\n\nQuestion: What happened to students who read only before exams?', 'They wrote the clearest essays', 'They stopped reading', 'They showed little improvement', 'They gained the richest vocabulary', 'c', 'The passage states they improved very little.', 'easy', '738e03200855edcd8b0fab8144398bef');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: A survey of students found that those who read for even twenty minutes a day had a richer vocabulary and wrote clearer essays. The researchers noted that the type of reading did not matter as much as the regular habit. Students who read only before exams showed little improvement.\n\nQuestion: Which title suits the passage best?', 'Why Exams Are Difficult', 'How to Write Long Essays', 'The Cost of School Books', 'The Power of a Daily Reading Habit', 'd', 'The passage is about the benefit of daily reading.', 'medium', 'bb18b3272a9506d3fa4e9e9f387b79a3');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Electric vehicles produce no exhaust while driving, which improves air quality in crowded cities. Yet their batteries need minerals that are mined with heavy machinery, and the electricity used to charge them may come from coal. Therefore, experts say that the real environmental benefit of electric vehicles depends on how clean the power supply is.\n\nQuestion: According to the experts, the environmental benefit of electric vehicles depends on', 'how clean the electricity supply is', 'the colour of the vehicle', 'the number of roads in a city', 'the price of petrol', 'a', 'This is stated in the last sentence.', 'medium', 'c17d565713e9aa1406351bee43500344');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Electric vehicles produce no exhaust while driving, which improves air quality in crowded cities. Yet their batteries need minerals that are mined with heavy machinery, and the electricity used to charge them may come from coal. Therefore, experts say that the real environmental benefit of electric vehicles depends on how clean the power supply is.\n\nQuestion: Which drawback of electric vehicles is mentioned?', 'Battery minerals are mined with heavy machinery', 'They are always slower', 'They produce more exhaust', 'They cannot be driven in cities', 'a', 'The passage names mining of battery minerals.', 'easy', '39fd8407f49802fe0c47857e706421be');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Electric vehicles produce no exhaust while driving, which improves air quality in crowded cities. Yet their batteries need minerals that are mined with heavy machinery, and the electricity used to charge them may come from coal. Therefore, experts say that the real environmental benefit of electric vehicles depends on how clean the power supply is.\n\nQuestion: The word \'Yet\' in the passage introduces', 'a repeated point', 'a final conclusion', 'a contrast to the earlier benefit', 'a personal opinion', 'c', '\'Yet\' turns from the benefit to the limitations.', 'hard', '8d561050631c7962cfa9fcad3eabf7d8');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Teenagers need about eight to ten hours of sleep, but many get much less because of late-night screen use and early school hours. Lack of sleep affects memory and mood, and it can make it harder to concentrate in class. Simple habits, like keeping phones away from the bed, can help.\n\nQuestion: How many hours of sleep do teenagers need, according to the passage?', 'Eight to ten hours', 'Eleven to twelve hours', 'Five to six hours', 'Six to seven hours', 'a', 'The first sentence gives the range.', 'easy', 'ff88dea93da8cce501d3ebd9b89d36af');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Teenagers need about eight to ten hours of sleep, but many get much less because of late-night screen use and early school hours. Lack of sleep affects memory and mood, and it can make it harder to concentrate in class. Simple habits, like keeping phones away from the bed, can help.\n\nQuestion: Which of these is NOT mentioned as an effect of too little sleep?', 'Bad mood', 'Difficulty concentrating', 'Weight gain', 'Poor memory', 'c', 'Weight gain does not appear in the passage.', 'medium', '664dbd4429bce93f756488707b369966');
INSERT IGNORE INTO aptitude_questions (category, topic, subtopic, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, q_hash) VALUES ('Verbal Ability', 'reading-comprehension', 'Passage questions', 'Passage: Teenagers need about eight to ten hours of sleep, but many get much less because of late-night screen use and early school hours. Lack of sleep affects memory and mood, and it can make it harder to concentrate in class. Simple habits, like keeping phones away from the bed, can help.\n\nQuestion: What simple habit does the passage suggest?', 'Starting school later', 'Sleeping during the day', 'Studying at midnight', 'Keeping phones away from the bed', 'd', 'It is mentioned in the final sentence.', 'easy', 'ecd8d3b4abc65701af96f0e63e45f9b0');
